package servers_test

// L756F (THROWAWAY ab/l756f-diag-20261115, not for merge): the registry columns of the RULE 74 A/B with an A/A twin of the #756 fix candidate (celeris PR #1306, default loop reserve n/8 -> n/4)
// against FINAL main (servers/l756f_arms.go, generated by l756f-gen.py). The expectations are stated here, not derived from the code under test; the two pins come from servers/celeris/go.mod and
// servers/celeris_pr1306/go.mod, and servers/celeris_pr1306 must be a byte copy of the servers/celeris adapter sources (only go.mod / go.sum differ: celeris is the ONLY thing that differs between A and B).

import (
	"bytes"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

// arm -> the exact column env (every column also carries the sampler).
var l756fWant = map[string]map[string]string{
	"a":   {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"a2":  {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"b":   {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"ag":  {"PROBATORIUM_SCHED_SAMPLE": "1", "GOGC": "400"},
	"bg":  {"PROBATORIUM_SCHED_SAMPLE": "1", "GOGC": "400"},
	"ctl": {"PROBATORIUM_SCHED_SAMPLE": "1"},
}

var l756fName = regexp.MustCompile(`^l756f-([0-9]{3})-r([1-5])-(a|a2|b|ag|bg|ctl)-(epoll-h1-sync|std-h1)$`)
var l756fPinRe = regexp.MustCompile(`(?m)^\s*github\.com/goceleris/celeris (v\S+)\s*$`)

func l756fPin(t *testing.T, dir string) string {
	t.Helper()
	mod, err := os.ReadFile(filepath.Join(dir, "go.mod"))
	if err != nil {
		t.Fatal(err)
	}
	m := l756fPinRe.FindSubmatch(mod)
	if m == nil {
		t.Fatalf("no celeris require in %s/go.mod", dir)
	}
	return string(m[1])
}

func l756fItoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b []byte
	for ; n > 0; n /= 10 {
		b = append([]byte{byte('0' + n%10)}, b...)
	}
	return string(b)
}

func TestL756FColumns(t *testing.T) {
	var cols []servers.Adapter
	for n, a := range servers.Registry {
		if strings.HasPrefix(n, "l756f-") {
			cols = append(cols, a)
		}
	}
	sort.Slice(cols, func(i, j int) bool { return cols[i].Name < cols[j].Name })
	if len(cols) != 30 {
		t.Fatalf("%d l756f columns, want 30 (5 reps x 6 arms)", len(cols))
	}
	mainPin, fixPin := l756fPin(t, "celeris"), l756fPin(t, "celeris_pr1306")
	if mainPin == fixPin {
		t.Fatalf("servers/celeris and servers/celeris_pr1306 pin the same celeris %s: there is no A/B", mainPin)
	}
	perRep := map[string]map[string]int{}
	baseLoop, baseCtl := servers.Registry["celeris-epoll-h1-sync"], servers.Registry["celeris-std-h1"]
	for i, a := range cols {
		mm := l756fName.FindStringSubmatch(a.Name)
		if mm == nil {
			t.Fatalf("column name %q", a.Name)
		}
		seq, rep, arm, eng := mm[1], mm[2], mm[3], mm[4]
		if want := i + 1; seq != strings.Repeat("0", 3-len(l756fItoa(want)))+l756fItoa(want) {
			t.Errorf("%s: seq %s is not the sorted position %d", a.Name, seq, want)
		}
		if perRep[rep] == nil {
			perRep[rep] = map[string]int{}
		}
		perRep[rep][arm]++
		base := baseLoop
		if arm == "ctl" {
			base = baseCtl
		}
		if (arm == "ctl") != (eng == "std-h1") || a.Engine != eng || a.Engine != base.Engine || a.Capabilities != base.Capabilities || a.Category != base.Category || a.Language != base.Language {
			t.Errorf("%s: engine / capabilities differ from its base column", a.Name)
		}
		wantMod, wantPin := "servers/celeris", mainPin
		if arm == "b" || arm == "bg" {
			wantMod, wantPin = "servers/celeris_pr1306", fixPin
		}
		if a.Framework != "celeris-l756f-"+arm || a.FrameworkVersion != wantPin {
			t.Errorf("%s: framework %s version %s, want celeris-l756f-%s / %s", a.Name, a.Framework, a.FrameworkVersion, arm, wantPin)
		}
		if gb, ok := a.Bin.(servers.GoBinary); !ok || gb.ModuleDir != wantMod {
			t.Errorf("%s: bin %#v, want module %s", a.Name, a.Bin, wantMod)
		}
		want := l756fWant[arm]
		if len(a.SUTEnv) != len(want) {
			t.Errorf("%s: SUTEnv %v, want %v", a.Name, a.SUTEnv, want)
		}
		for k, v := range want {
			if a.SUTEnv[k] != v {
				t.Errorf("%s: SUTEnv[%s] = %q, want %q", a.Name, k, a.SUTEnv[k], v)
			}
		}
		p, ok := a.RatedPlans["ws-large-echo"]
		if !ok || len(a.RatedPlans) != 1 || len(p.Fractions) != 0 || len(p.AbsoluteRPS) != 3 || p.AbsoluteRPS[0] != 8376 || p.AbsoluteRPS[1] != 16753 || p.AbsoluteRPS[2] != 25129 || p.Placeholder || p.SaturationOnly {
			t.Errorf("%s: rated plans %#v, want exactly ws-large-echo: no fractions, absolute 8376, 16753 and 25129", a.Name, a.RatedPlans)
		}
		if a.Baseline {
			t.Errorf("%s: Baseline is set", a.Name)
		}
	}
	for rep, arms := range perRep {
		if len(arms) != 6 {
			t.Errorf("rep %s has %d arms, want 6", rep, len(arms))
		}
		for arm, n := range arms {
			if n != 1 {
				t.Errorf("rep %s arm %s %d times", rep, arm, n)
			}
		}
	}
	if len(perRep) != 5 {
		t.Errorf("%d reps, want 5", len(perRep))
	}
}

// TestL756FFixModuleIsAByteCopyOfTheMainAdapter: B differs from A by the celeris pin ONLY (RULE 74: nothing else may move). Every file of servers/celeris is in servers/celeris_pr1306 with the same bytes,
// except go.mod / go.sum (the module path and the celeris pin / its sums); no extra file.
func TestL756FFixModuleIsAByteCopyOfTheMainAdapter(t *testing.T) {
	ents, err := os.ReadDir("celeris")
	if err != nil {
		t.Fatal(err)
	}
	seen := map[string]bool{}
	for _, e := range ents {
		if e.IsDir() {
			t.Errorf("servers/celeris has a directory %s: the byte-copy test does not cover it", e.Name())
			continue
		}
		n := e.Name()
		seen[n] = true
		if n == "go.mod" || n == "go.sum" || n == "celeris" { // celeris = the built binary, .gitignored
			continue
		}
		a, err1 := os.ReadFile(filepath.Join("celeris", n))
		b, err2 := os.ReadFile(filepath.Join("celeris_pr1306", n))
		if err1 != nil || err2 != nil {
			t.Errorf("%s: %v / %v", n, err1, err2)
			continue
		}
		if !bytes.Equal(a, b) {
			t.Errorf("servers/celeris_pr1306/%s differs from servers/celeris/%s", n, n)
		}
	}
	ents2, _ := os.ReadDir("celeris_pr1306")
	for _, e := range ents2 {
		if n := e.Name(); !seen[n] && n != "celeris_pr1306" { // the built binary is named after the directory
			t.Errorf("servers/celeris_pr1306/%s has no counterpart in servers/celeris", n)
		}
	}
	ma, _ := os.ReadFile(filepath.Join("celeris", "go.mod"))
	mb, _ := os.ReadFile(filepath.Join("celeris_pr1306", "go.mod"))
	norm := func(b []byte, mod, pin string) string {
		return strings.ReplaceAll(strings.ReplaceAll(string(b), "servers/"+mod, "servers/MOD"), pin, "PIN")
	}
	if norm(ma, "celeris", l756fPin(t, "celeris")) != norm(mb, "celeris_pr1306", l756fPin(t, "celeris_pr1306")) {
		t.Errorf("go.mod of servers/celeris_pr1306 differs from servers/celeris by more than the module path and the celeris pin")
	}
}
